/// <summary>
///     Extension class for DlvMode
/// </summary>
[ExtensionOf(tableStr(DlvMode))]
final class AVADlvModeTbl_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>avaTxtOrId</c> method.
/// </summary>
/// <param name="_id">
///     <c>DlvModeId</c> as type
/// </param>
/// <param name="_languageId">
///     <c>LanguageId</c> as type
/// </param>
/// <returns>
///    <c>FreeText</c> as return value
/// </returns>
public static FreeText avaTxtOrId(  DlvModeId   _id, 
                                    LanguageId  _languageId = CompanyInfo::languageId() )
{
    FreeText retVal;

    if(_id && DlvMode::exist(_id))
    {
        //@SYS210
        retVal      = DlvMode::txt( _id, 
                                    _languageId );
        if(!retVal)
        {
            retVal  = _id;
        }
    }
    return retVal;
}

 /// <summary>
 ///     AVA <c>avaSalesPickupDlvModeId</c> method.
 ///     AVA - Schneider 03.06.2024
 /// </summary>
 /// <returns>
 ///     <c>DlvModeId</c> as return value
 /// </returns>
public static DlvModeId avaSalesPickupDlvModeId()
{
     DlvModeId   locDlvModePickup;
     DlvMode     locDlvMode;

     select firstonly1 locDlvMode
     order by locDlvMode.Code
     where locDlvMode.KCS_ColComActive == NoYes::Yes;

     locDlvModePickup = locDlvMode.Code;

     return locDlvModePickup;
}
